mapper.select:
SELECT 
FROM underwriting_decisions


        AND decision_id = #{q.decisionId}
        AND application_id = #{q.applicationId}
        AND customer_id = #{q.customerId}
        AND gender = #{q.gender}
        AND occupation = #{q.occupation}
        AND risk_level = #{q.riskLevel}
        AND underwriting_result = #{q.underwritingResult}
        AND has_social_insurance = #{q.hasSocialInsurance}
        AND smoking_status = #{q.smokingStatus}
        AND drinking_status = #{q.drinkingStatus}
        AND created_by = #{q.createdBy}

    AND created_at >= #{createdFrom}
    AND created_at <= #{createdTo}
    AND updated_at >= #{updatedFrom}
    AND updated_at <= #{updatedTo}

ORDER BY updated_at DESC NULLS LAST, decision_id
